Item.method_code:
return window.ModulesManager.using(
	['aras.innovator.core.ItemWindow/DefaultItemWindowView',
	'aras.innovator.core.ItemWindow/DefaultItemWindowCreator'], function(View, Creator) {
		const itemID = inDom.getAttribute('id');
		const win = aras.uiFindAndSetFocusWindowEx(itemID);
		let view;
		let creator;

		if (win !== null) {
			return;
		}

		if (aras.isTempEx(inDom)) {
			view = new View(inDom, inArgs);
			creator = new Creator(view);
			return creator.ShowView();
		}

		const fileTypeId = aras.getItemProperty(inDom, 'file_type');
		const fileType = aras.getItemFromServerWithRels('FileType', fileTypeId, 'name', 'View With', 'client, application, related_id(viewer_url)', 1).node;
		const viewer = (fileType) ? fileType.selectSingleNode('Relationships/Item[client=\'js\'][application/@is_null=\'1\']/related_id/Item/viewer_url') : null;

		if (viewer) {
			view = new View(inDom, inArgs);
			creator = new Creator(view);
			return creator.ShowView();
		}

		let fileURL;
		try {
			fileURL = aras.IomInnovator.getFileUrl(inDom.getAttribute('id'), aras.Enums.UrlType.SecurityToken);
		}
		catch {
			aras.AlertError(aras.getResource('', 'ui_methods_ex.failed_get_file'), aras.getResource('', 'ui_methods_ex.failed_to_open_file'),
				aras.getResource('', 'common.client_side_err'));

			return;
		}

		const wnd = window.open('','', 'scrollbars=yes,resizable=yes,status=no');
		wnd.opener = null;
		wnd.location = fileURL;
	});
